import functools, traceback
from send_email import send_email  # from Week 9

def alert_on_crash(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except Exception as e:
            error_msg = traceback.format_exc()
            send_email(
                subject=f'FORGE ALERT: {fn.__name__} crashed',
                body=f'Error:\n{error_msg}'
            )
            raise  # re-raise so the error still propagates
    return wrapper

